// Pasa una dirección IPv4 de decimal con puntos a binario y a un solo número
function aBinario(ip) {
  return ip.split('.').map(o => Number(o).toString(2).padStart(8, '0')).join('.');
}
function aEntero(ip) {
  return ip.split('.').reduce((acum, o) => acum * 256 + Number(o), 0);
}
function claseHistorica(ip) {
  const primero = Number(ip.split('.')[0]);
  if (primero < 128) return 'A';
  if (primero < 192) return 'B';
  if (primero < 224) return 'C';
  if (primero < 240) return 'D (multicast)';
  return 'E (reservada)';
}
for (const ip of ['192.0.2.2', '172.16.5.9', '10.1.2.3', '224.0.0.251', '240.0.0.1']) {
  console.log(ip.padEnd(14), aBinario(ip), String(aEntero(ip)).padStart(10), 'clase', claseHistorica(ip));
}
console.log('Cantidad total de direcciones:', 2 ** 32);
